    var group = opcion.getAttribute('group');
    var questionId = question.id;

    // Si ya está respondida, no permitir cambiar (opcional: podría permitirse, pero mantendremos una sola respuesta)
    if (respuestas[questionId]) return;

    // Deseleccionar otras opciones en la misma pregunta
    var opcionesGrupo = question.querySelectorAll('upao-choice[group="' + group + '"]');
    opcionesGrupo.forEach(function(o) {
      o.classList.remove('is-selected');
    });

