    // Eliminar feedback previo en la pregunta
    var feedbackAnterior = question.querySelector('.ova-feedback');
    if (feedbackAnterior) feedbackAnterior.remove();

    var feedbackDiv = document.createElement('div');
    feedbackDiv.className = 'ova-feedback' + (esCorrecta ? ' ova-feedback--ok' : ' ova-feedback--bad');
    feedbackDiv.textContent = feedback;
    feedbackDiv.setAttribute('aria-live', 'polite');
    question.appendChild(feedbackDiv);

    // Actualizar contadores
    preguntasRespondidas++;
    var correctas = 0;
    for (var key in respuestas) {
      var pregunta = document.getElementById(key);
      if (pregunta) {
