        var seleccionada = respuestas[key];
        for (var i = 0; i < opcionesPregunta.length; i++) {
          if (opcionesPregunta[i].getAttribute('value') === seleccionada) {
            if (opcionesPregunta[i].getAttribute('correct') === 'true') {
